'use client';
import { useEffect, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Link2, Upload, ArrowLeft, Loader2 } from 'lucide-react';
import CreateButton from '@/components/CreateButton';
import Link from 'next/link';

export default function NewsEditorPage({ params }: { params: { id?: string } }) {
  const router = useRouter();
  const isEdit = !!params.id;

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [published, setPublished] = useState(false);
  const [imageUrl, setImageUrl] = useState('');
  const [uploadMode, setUploadMode] = useState<'url' | 'file'>('url');
  const [loading, setLoading] = useState(false);
  const [fetching, setFetching] = useState(isEdit);

  // Fetch data if in Edit Mode
  useEffect(() => {
    if (isEdit) {
      fetch(`http://localhost:5001/api/news/${params.id}`)
        .then(res => res.json())
        .then(data => {
          setTitle(data.title);
          setContent(data.content);
          setPublished(data.published);
          setImageUrl(data.image_url || '');
          setFetching(false);
        })
        .catch(() => setFetching(false));
    }
  }, [isEdit, params.id]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) return alert('Max 2MB');
      const reader = new FileReader();
      reader.onloadend = () => setImageUrl(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    
    const url = isEdit ? `http://localhost:5001/api/news/${params.id}` : 'http://localhost:5001/api/news';
    const method = isEdit ? 'PUT' : 'POST';

    const res = await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title, content, published, image_url: imageUrl }),
      credentials: 'include',
    });

    if (res.ok) router.push('/admin/news');
    else setLoading(false);
  };

  if (fetching) return <div className="min-h-screen bg-[#020617] flex items-center justify-center"><Loader2 className="animate-spin text-red-600" /></div>;

  return (
    <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 italic">
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-[2.5rem] overflow-hidden shadow-2xl">
        <div className="bg-slate-950 p-8 border-b border-slate-800 flex justify-between items-center">
           <h1 className="text-2xl font-black text-white uppercase tracking-tighter flex items-center gap-3">
             <span className="w-1.5 h-6 bg-red-600"></span> {isEdit ? 'Update' : 'Initialize'} Article
           </h1>
           <Link href="/admin/news" className="text-slate-500 hover:text-white transition-colors"><ArrowLeft size={20}/></Link>
        </div>
        
        <form onSubmit={handleSubmit} className="p-8 space-y-6 text-white">
          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 px-1">Headlines</label>
            <input value={title} onChange={(e) => setTitle(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-sm focus:ring-1 focus:ring-red-600 outline-none" required />
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 px-1">Visual Asset</label>
            <div className="flex gap-2 p-1 bg-slate-950 rounded-xl border border-slate-800">
              <button type="button" onClick={() => setUploadMode('url')} className={`flex-1 py-2 text-[9px] font-black uppercase tracking-widest rounded-lg flex items-center justify-center gap-2 transition-all ${uploadMode === 'url' ? 'bg-red-600 text-white' : 'text-slate-500'}`}><Link2 size={12}/> URL</button>
              <button type="button" onClick={() => setUploadMode('file')} className={`flex-1 py-2 text-[9px] font-black uppercase tracking-widest rounded-lg flex items-center justify-center gap-2 transition-all ${uploadMode === 'file' ? 'bg-red-600 text-white' : 'text-slate-500'}`}><Upload size={12}/> File</button>
            </div>
            {uploadMode === 'url' ? (
              <input placeholder="https://..." className="w-full bg-slate-950 border border-slate-800 p-4 rounded-xl text-sm outline-none focus:border-red-600 transition-all" value={imageUrl} onChange={e => setImageUrl(e.target.value)} />
            ) : (
              <div className="relative w-full bg-slate-950 border-2 border-dashed border-slate-800 rounded-xl p-6 text-center hover:border-red-600 transition-colors cursor-pointer">
                <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
                {imageUrl ? <img src={imageUrl} className="h-20 mx-auto object-cover rounded-lg" /> : <Upload size={20} className="mx-auto text-slate-500" />}
              </div>
            )}
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 px-1">Content</label>
            <textarea value={content} onChange={(e) => setContent(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-sm min-h-[150px] focus:ring-1 focus:ring-red-600 outline-none resize-none" required />
          </div>

          <div className="flex items-center gap-4 py-2">
             <input type="checkbox" checked={published} onChange={(e) => setPublished(e.target.checked)} className="w-5 h-5 accent-red-600 cursor-pointer" />
             <span className="text-xs font-bold text-slate-400 uppercase tracking-wide">Broadcast Live</span>
          </div>

          <CreateButton type="submit" disabled={loading}>{loading ? 'Processing...' : isEdit ? 'Save Changes' : 'Publish Entry'}</CreateButton>
        </form>
      </div>
    </div>
  );
}